BEGIN;
CREATE TABLE IF NOT EXISTS cultivation_lots(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,facility_id TEXT NOT NULL,batch_id TEXT NOT NULL,tag_id TEXT NOT NULL,jurisdiction TEXT NOT NULL,cultivar TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('propagation','vegetative','flowering','harvest_hold','tested','packaged','transferred','destroyed','recalled')),record JSONB NOT NULL,idempotency_key TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,tag_id),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS cultivation_lot_events(id BIGSERIAL PRIMARY KEY,lot_id BIGINT NOT NULL REFERENCES cultivation_lots(id),tenant_id TEXT NOT NULL,actor_id TEXT NOT NULL,event_type TEXT NOT NULL,from_state TEXT,to_state TEXT,idempotency_key TEXT,evidence_digest TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(lot_id,idempotency_key));
CREATE TABLE IF NOT EXISTS cultivation_sync_jobs(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,provider TEXT NOT NULL CHECK(provider IN('metrc','biotrack','lab','sensor','pos','identity')),idempotency_key TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','succeeded','failed','quarantined')),payload JSONB NOT NULL,requested_by TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,failure_code TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,provider,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_cultivation_lots_tenant_state ON cultivation_lots(tenant_id,state,jurisdiction);
COMMIT;
